11	/**
12	 * Business Email — mailbox hosting per registered domain.
13	 *
14	 * An `EmailPlan` is a pricing tier (N mailboxes, GB/mailbox, price, term). A
15	 * customer subscribes one of their own domains to a tier (`EmailSubscription`),
16	 * which debits the wallet, then manages individual `Mailbox` rows under it.
17	 *
18	 * IMPORTANT — this is the product + ordering scaffold. Actual mail delivery is a
19	 * pluggable mail-provider integration that is NOT wired up yet. We therefore do
20	 * NOT provision real mailboxes or send anything: creating a Mailbox row records
21	 * intent; the address is marked "provisioning" until the provider integration
22	 * lands. Nothing here fakes delivery.
23	 *
24	 * This module owns:
25	 *   - orderEmailHosting (customer subscribe)
26	 *   - addMailbox / removeMailbox (customer mailbox management)
27	 *   - adminSaveEmailPlan / adminToggleEmailPlan / adminDeleteEmailPlan (CRUD)
28	 */
29	
30	type Result = { error?: string; ok?: boolean };
31	
32	// ---------- Admin CRUD (billing area) ----------
33	
34	const planSchema = z.object({
35	  id: z.string().optional(),
36	  name: z.string().min(2).max(80),
37	  mailboxes: z.coerce.number().int().min(1).max(100000),
38	  storageGB: z.coerce.number().int().min(1).max(100000),
39	  priceCents: z.coerce.number().int().min(0).max(100000000),
40	  termMonths: z.coerce.number().int().min(1).max(36),
41	  sortOrder: z.coerce.number().int().min(0).max(100000),
42	});
43	
44	/** Create or update an EmailPlan tier. ADMIN/BILLING only, audit-logged. */
45	export async function adminSaveEmailPlan(
46	  prev: Result | undefined,
47	  formData: FormData,
48	): Promise<Result> {
49	  const admin = await requireArea("billing");
50	
51	  const parsed = planSchema.safeParse({
52	    id: formData.get("id") || undefined,
53	    name: formData.get("name"),
54	    mailboxes: formData.get("mailboxes"),
55	    storageGB: formData.get("storageGB"),
56	    priceCents: formData.get("priceCents"),
57	    termMonths: formData.get("termMonths"),
58	    sortOrder: formData.get("sortOrder") ?? 0,
59	  });
60	  if (!parsed.success) {
61	    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
62	  }
63	  const d = parsed.data;
64	  const active = formData.get("active") === "on";
65	
66	  const data = {
67	    name: d.name.trim(),
68	    mailboxes: d.mailboxes,
69	    storageGB: d.storageGB,
70	    priceCents: d.priceCents,
71	    termMonths: d.termMonths,
72	    active,
73	    sortOrder: d.sortOrder,
74	  };
75	
76	  if (d.id) {
77	    const existing = await db.emailPlan.findUnique({ where: { id: d.id } });
78	    if (!existing) return { error: "Tier not found." };
79	    await db.emailPlan.update({ where: { id: d.id }, data });
80	  } else {
81	    await db.emailPlan.create({ data });
82	  }
83	
84	  await db.auditLog.create({
85	    data: {
86	      userId: admin.id,
87	      action: d.id ? "emailplan.update" : "emailplan.create",
88	      detail: `${data.name} — ${data.mailboxes} mbx / ${data.storageGB}GB (${(data.priceCents / 100).toFixed(2)}/${data.termMonths}mo)`,
89	    },
90	  });
91	  revalidatePath("/admin/email-plans");
92	  return { ok: true };
93	}
