95	/** Flip a tier's active flag. */
96	export async function adminToggleEmailPlan(id: string): Promise<void> {
97	  const admin = await requireArea("billing");
98	  const plan = await db.emailPlan.findUnique({ where: { id } });
99	  if (!plan) return;
100	  await db.emailPlan.update({ where: { id }, data: { active: !plan.active } });
101	  await db.auditLog.create({
102	    data: { userId: admin.id, action: "emailplan.toggle", detail: `${plan.name} → active=${!plan.active}` },
103	  });
104	  revalidatePath("/admin/email-plans");
105	}
