107	/** Delete a tier. Refused while subscriptions reference it. */
108	export async function adminDeleteEmailPlan(id: string): Promise<Result> {
109	  const admin = await requireArea("billing");
110	  const plan = await db.emailPlan.findUnique({
111	    where: { id },
112	    include: { _count: { select: { subscriptions: true } } },
113	  });
114	  if (!plan) return { error: "Tier not found." };
115	  if (plan._count.subscriptions > 0) {
116	    return {
117	      error: `Can't delete — ${plan._count.subscriptions} subscription(s) use this tier. Disable it instead.`,
118	    };
119	  }
120	  await db.emailPlan.delete({ where: { id } });
121	  await db.auditLog.create({
122	    data: { userId: admin.id, action: "emailplan.delete", detail: plan.name },
123	  });
124	  revalidatePath("/admin/email-plans");
125	  return { ok: true };
126	}
