128	// ---------- Customer ordering ----------
129	
130	/**
131	 * Subscribe one of the caller's registered domains to an email plan. Validates
132	 * domain ownership + plan availability, then atomically debits the wallet and
133	 * creates the EmailSubscription with an expiry set from the plan term.
134	 *
135	 * The subscription is created ACTIVE (billing-wise), but no mailboxes are
136	 * provisioned with a mail provider yet — that integration is pending, and the
137	 * UI surfaces every mailbox as "provisioning" until it lands.
138	 */
139	export async function orderEmailHosting(
140	  domainName: string,
141	  emailPlanId: string,
142	): Promise<Result> {
143	  const user = await requireUser();
144	
145	  const name = String(domainName ?? "").trim().toLowerCase();
146	  if (!name) return { error: "Choose a domain." };
147	
148	  // Ownership check — the domain must be registered to this user.
149	  const domain = await db.domain.findFirst({ where: { name, userId: user.id } });
150	  if (!domain) return { error: "That domain isn't in your account." };
151	
152	  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
153	  if (!plan || !plan.active) return { error: "That email plan isn't available." };
154	
155	  // One subscription per domain — refuse a duplicate.
156	  const dupe = await db.emailSubscription.findFirst({
157	    where: { userId: user.id, domainName: name, status: { not: "CANCELLED" } },
158	  });
159	  if (dupe) return { error: "This domain already has an email subscription." };
160	
161	  const chargeCents = plan.priceCents;
162	  if (user.balanceCents < chargeCents) {
163	    return { error: "Insufficient balance. Top up your wallet first." };
164	  }
165	
166	  try {
167	    await db.$transaction(async (tx) => {
168	      await debitWallet(tx, user.id, chargeCents);
169	      await tx.walletTransaction.create({
170	        data: {
171	          userId: user.id,
172	          amountCents: -chargeCents,
173	          description: `Business Email: ${plan.name} for ${name}`,
174	        },
175	      });
176	      await tx.emailSubscription.create({
177	        data: {
178	          userId: user.id,
179	          domainName: name,
180	          emailPlanId: plan.id,
181	          status: "ACTIVE",
182	          autoRenew: true,
183	          expiresAt: addMonths(new Date(), plan.termMonths),
184	        },
185	      });
186	    });
187	  } catch (e) {
188	    if (e instanceof InsufficientBalanceError) {
189	      return { error: "Insufficient balance. Top up your wallet first." };
190	    }
191	    throw e;
192	  }
193	
194	  await db.auditLog.create({
195	    data: {
196	      userId: user.id,
197	      action: "emailhosting.order",
198	      detail: `${name} plan=${plan.name}`,
199	    },
200	  });
201	  revalidatePath("/dashboard/email");
202	  return { ok: true };
203	}
