205	// Local-part of an email address: RFC-ish, conservative. No leading/trailing dot.
206	const localPartRe = /^[a-z0-9]+(?:[._-][a-z0-9]+)*$/;
207	
208	/**
209	 * Add a mailbox to a subscription the caller owns. Enforces the plan's mailbox
210	 * quota and address uniqueness within the subscription. No provider call is made
211	 * (integration pending) — this records the intended mailbox only.
212	 */
213	export async function addMailbox(subscriptionId: string, localPart: string): Promise<Result> {
214	  const user = await requireUser();
215	
216	  const sub = await db.emailSubscription.findUnique({
217	    where: { id: subscriptionId },
218	    include: { emailPlan: true, mailboxes: true },
219	  });
220	  if (!sub) return { error: "Subscription not found." };
221	  if (sub.userId !== user.id) return { error: "Not your subscription." };
222	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
223	
224	  const local = String(localPart ?? "").trim().toLowerCase();
225	  if (!localPartRe.test(local) || local.length > 64) {
226	    return { error: "Enter a valid mailbox name (letters, numbers, . _ - )." };
227	  }
228	
229	  const address = `${local}@${sub.domainName}`;
230	
231	  if (sub.mailboxes.length >= sub.emailPlan.mailboxes) {
232	    return {
233	      error: `Plan limit reached (${sub.emailPlan.mailboxes} mailbox${sub.emailPlan.mailboxes === 1 ? "" : "es"}). Upgrade to add more.`,
234	    };
235	  }
236	  if (sub.mailboxes.some((m) => m.address.toLowerCase() === address)) {
237	    return { error: "That address already exists." };
238	  }
239	
240	  await db.mailbox.create({
241	    data: { subscriptionId: sub.id, address },
242	  });
243	
244	  await db.auditLog.create({
245	    data: { userId: user.id, action: "mailbox.add", detail: address },
246	  });
247	  revalidatePath("/dashboard/email");
248	  return { ok: true };
249	}
250	
251	/** Remove a mailbox the caller owns (via its subscription). */
252	export async function removeMailbox(mailboxId: string): Promise<Result> {
253	  const user = await requireUser();
254	
255	  const mailbox = await db.mailbox.findUnique({
256	    where: { id: mailboxId },
257	    include: { subscription: true },
258	  });
259	  if (!mailbox) return { error: "Mailbox not found." };
260	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
261	
262	  await db.mailbox.delete({ where: { id: mailbox.id } });
263	
264	  await db.auditLog.create({
265	    data: { userId: user.id, action: "mailbox.remove", detail: mailbox.address },
266	  });
267	  revalidatePath("/dashboard/email");
268	  return { ok: true };
269	}
