176	export function timeAgo(d: Date): string {
177	  const s = Math.floor((Date.now() - d.getTime()) / 1000);
178	  if (s < 60) return `${s}s ago`;
179	  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
180	  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
181	  return `${Math.floor(s / 86400)}d ago`;
182	}
