// Mailcow REST API client.
//
// Plain server-side module (NO "use server") — safe to import from server
// actions, route handlers, server components and the worker; never bundled to
// the client. Talks to a self-hosted Mailcow instance over its REST API.
//
// Configuration is read from the environment at call time (never hardcoded):
//   MAILCOW_API_URL  e.g. https://mail.nxeon.cloud/api/v1
//   MAILCOW_API_KEY  the X-API-Key value
//
// Every function throws a clear Error on a non-success response (including when
// Mailcow itself replies with a `{type:"danger"|"error"}` payload) or when the
// integration is not configured. Callers that must stay failure-tolerant (the
// order flow) wrap these in try/catch.

export class MailcowError extends Error {
  constructor(
    message: string,
    public status?: number,
    public body?: unknown,
  ) {
    super(message);
    this.name = "MailcowError";
  }
}

/** Both env vars present and non-empty. */
export function mailcowConfigured(): boolean {
  return Boolean(
    process.env.MAILCOW_API_URL?.trim() && process.env.MAILCOW_API_KEY?.trim(),
  );
}

function config(): { base: string; key: string } {
  const base = process.env.MAILCOW_API_URL?.trim();
  const key = process.env.MAILCOW_API_KEY?.trim();
  if (!base || !key) {
    throw new MailcowError(
      "Mailcow not configured — set MAILCOW_API_URL and MAILCOW_API_KEY.",
    );
  }
  return { base: base.replace(/\/+$/, ""), key };
}

/**
 * Core request helper. Performs a fetch to `${MAILCOW_API_URL}${path}` with the
 * X-API-Key header, parses the JSON body, and throws a MailcowError on any
 * non-2xx status or on a Mailcow error payload.
 */
async function mcRequest(
  method: "GET" | "POST",
  path: string,
  body?: unknown,
): Promise<unknown> {
  const { base, key } = config();
  const url = `${base}${path.startsWith("/") ? path : `/${path}`}`;

  let res: Response;
  try {
    res = await fetch(url, {
      method,
      headers: {
        "X-API-Key": key,
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: body === undefined ? undefined : JSON.stringify(body),
      cache: "no-store",
    });
  } catch (e) {
    throw new MailcowError(
      `Mailcow unreachable (${method} ${path}): ${e instanceof Error ? e.message : String(e)}`,
    );
  }

  const text = await res.text();
  let parsed: unknown = text;
  try {
    parsed = text ? JSON.parse(text) : null;
  } catch {
    // leave parsed as raw text
  }

  if (!res.ok) {
    throw new MailcowError(
      `Mailcow ${method} ${path} -> HTTP ${res.status}`,
      res.status,
      parsed,
    );
  }

  assertNoApiError(parsed, `${method} ${path}`);
  return parsed;
}

/**
 * Mailcow POST endpoints return HTTP 200 even on logical failure, signalling the
 * outcome via `type` in the (array-wrapped) payload. Detect and surface those.
 */
function assertNoApiError(parsed: unknown, ctx: string): void {
  const entries = Array.isArray(parsed) ? parsed : [parsed];
  for (const entry of entries) {
    if (entry && typeof entry === "object" && "type" in entry) {
      const type = String((entry as { type: unknown }).type ?? "").toLowerCase();
      if (type === "danger" || type === "error") {
        const rawMsg = (entry as { msg?: unknown }).msg;
        const msg = Array.isArray(rawMsg) ? rawMsg.join(" ") : String(rawMsg ?? "unknown error");
        throw new MailcowError(`Mailcow ${ctx} failed: ${msg}`, undefined, parsed);
      }
    }
  }
}

// ---------- Mutations ----------

/** Create a mail domain (idempotent-ish: if it already exists Mailcow errors,
 * which callers may ignore). */
export async function mcCreateDomain(domain: string): Promise<unknown> {
  return mcRequest("POST", "/add/domain", {
    domain,
    description: `nxeon ${domain}`,
    aliases: 400,
    mailboxes: 100,
    defquota: 1024,
    maxquota: 102400,
    quota: 102400,
    active: "1",
    restart_sogo: "0",
  });
}

/** True if the domain already exists in Mailcow. */
export async function mcDomainExists(domain: string): Promise<boolean> {
  try {
    const res = await mcRequest("GET", `/get/domain/${encodeURIComponent(domain)}`);
    // Mailcow returns {} (or []) for an unknown domain, or the domain object.
    if (!res) return false;
    if (Array.isArray(res)) return res.length > 0;
    if (typeof res === "object") {
      return "domain_name" in res || "domain" in res;
    }
    return false;
  } catch {
    return false;
  }
}

export async function mcCreateMailbox(opts: {
  localPart: string;
  domain: string;
  name: string;
  password: string;
  quotaMB: number;
}): Promise<unknown> {
  return mcRequest("POST", "/add/mailbox", {
    local_part: opts.localPart,
    domain: opts.domain,
    name: opts.name,
    password: opts.password,
    password2: opts.password,
    quota: opts.quotaMB,
    active: "1",
  });
}

/** Activate / deactivate a mailbox (used for suspend/resume). */
export async function mcSetMailboxActive(address: string, active: boolean): Promise<unknown> {
  return mcRequest("POST", "/edit/mailbox", {
    items: [address],
    attr: { active: active ? "1" : "0" },
  });
}

/** Change a mailbox quota (MB). */
export async function mcSetQuota(address: string, quotaMB: number): Promise<unknown> {
  return mcRequest("POST", "/edit/mailbox", {
    items: [address],
    attr: { quota: quotaMB },
  });
}

/** Delete a mailbox. */
export async function mcDeleteMailbox(address: string): Promise<unknown> {
  return mcRequest("POST", "/delete/mailbox", [address]);
}

// ---------- Analytics ----------

export type MailStats = {
  configured: true;
  domains: number;
  mailboxes: number;
  postfix: {
    sampled: number;
    sent: number;
    deferred: number;
    bounced: number;
    rejected: number;
    other: number;
  };
  rspamd: {
    sampled: number;
    actions: Record<string, number>;
    spam: number; // reject + add header + rewrite subject
    clean: number; // no action + greylist / soft reject
  };
};

function asArray(v: unknown): unknown[] {
  if (Array.isArray(v)) return v;
  if (v && typeof v === "object" && Array.isArray((v as { rows?: unknown[] }).rows)) {
    return (v as { rows: unknown[] }).rows;
  }
  return [];
}

/**
 * Pull recent postfix + rspamd logs and domain/mailbox counts for the admin
 * deliverability view. Throws (MailcowError) if not configured or unreachable —
 * the admin page catches that and shows a graceful fallback.
 */
export async function mcStats(sample = 400): Promise<MailStats> {
  config(); // throws early with a clear message if not configured

  const [domainsRaw, mailboxesRaw, postfixRaw, rspamdRaw] = await Promise.all([
    mcRequest("GET", "/get/domain/all").catch(() => []),
    mcRequest("GET", "/get/mailbox/all").catch(() => []),
    mcRequest("GET", `/get/logs/postfix/${sample}`).catch(() => []),
    mcRequest("GET", `/get/logs/rspamd-history/${sample}`).catch(() => []),
  ]);

  const postfixLogs = asArray(postfixRaw);
  const postfix = { sampled: postfixLogs.length, sent: 0, deferred: 0, bounced: 0, rejected: 0, other: 0 };
  for (const entry of postfixLogs) {
    const msg = String(
      (entry as { message?: unknown })?.message ??
        (entry && typeof entry === "object" ? JSON.stringify(entry) : entry) ??
        "",
    ).toLowerCase();
    if (msg.includes("status=sent")) postfix.sent++;
    else if (msg.includes("status=deferred")) postfix.deferred++;
    else if (msg.includes("status=bounced")) postfix.bounced++;
    else if (msg.includes("reject:") || msg.includes("status=reject")) postfix.rejected++;
    else postfix.other++;
  }

  const rspamdLogs = asArray(rspamdRaw);
  const actions: Record<string, number> = {};
  let spam = 0;
  let clean = 0;
  for (const entry of rspamdLogs) {
    const action = String((entry as { action?: unknown })?.action ?? "unknown").toLowerCase();
    actions[action] = (actions[action] ?? 0) + 1;
    if (action === "reject" || action === "add header" || action === "rewrite subject") spam++;
    else clean++;
  }

  return {
    configured: true,
    domains: asArray(domainsRaw).length,
    mailboxes: asArray(mailboxesRaw).length,
    postfix,
    rspamd: { sampled: rspamdLogs.length, actions, spam, clean },
  };
}

