import { revalidatePath } from "next/cache";
import { randomBytes } from "node:crypto";
import { z } from "zod";
import { db } from "./db";
import { requireUser } from "./auth";
import { requireArea } from "./rbac";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { addMonths } from "./billing-terms";
import { encryptSecret } from "./crypto-box";
import {
  mailcowConfigured,
  mcCreateDomain,
  mcDomainExists,
  mcCreateMailbox,
  mcDeleteMailbox,
  mcSetMailboxActive,
} from "./mailcow";

 * Mail delivery runs through a self-hosted Mailcow server, reached via lib/mailcow.ts
 * (config from MAILCOW_API_URL / MAILCOW_API_KEY). Creating a Mailbox row records
 * intent (status PROVISIONING); we then attempt to provision the real mailbox on
 * Mailcow and flip the row to ACTIVE, or FAILED if the call errors. All Mailcow
 * calls are additive and failure-tolerant — a Mailcow outage never breaks the
 * order flow; the row persists and can be retried via retryMailboxProvision.
 *
 * This module owns:
 *   - orderEmailHosting (customer subscribe)
 *   - addMailbox / removeMailbox / retryMailboxProvision (customer mailbox management)
 *   - adminSaveEmailPlan / adminToggleEmailPlan / adminDeleteEmailPlan (CRUD)
 */

type Result = { error?: string; ok?: boolean };

/**
 * Provision (or re-provision) a mailbox on Mailcow. Never throws — records the
 * outcome on the Mailbox row (status ACTIVE on success, FAILED on error) and
 * returns it. When Mailcow isn't configured the row is left PROVISIONING so it
 * can be picked up once the integration is wired.
 */
async function provisionMailboxOnMailcow(mailbox: {
  id: string;
  address: string;
  quotaMB: number | null;
  subscription: { domainName: string };
}): Promise<"ACTIVE" | "FAILED" | "PROVISIONING"> {
  if (!mailcowConfigured()) return "PROVISIONING";

  const [localPart] = mailbox.address.split("@");
  const domain = mailbox.subscription.domainName;
  const quotaMB = mailbox.quotaMB ?? 1024;

  try {
    // Ensure the mail domain exists before adding the mailbox.
    if (!(await mcDomainExists(domain))) {
      // A concurrent create or pre-existing domain can still error here; ignore
      // and let the mailbox add be the real signal.
      await mcCreateDomain(domain).catch(() => {});
    }

    const password = randomBytes(18).toString("base64url");
    await mcCreateMailbox({
      localPart,
      domain,
      name: mailbox.address,
      password,
      quotaMB,
    });

    await db.mailbox.update({
      where: { id: mailbox.id },
      data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
    });
    return "ACTIVE";
  } catch (e) {
    await db.mailbox
      .update({ where: { id: mailbox.id }, data: { status: "FAILED" } })
      .catch(() => {});
    console.warn(`[mailcow] provisioning ${mailbox.address} failed:`, e);
    return "FAILED";
  }
}

