"use server";

import { requireArea } from "./rbac";
import { mailcowConfigured, mcStats, type MailStats } from "./mailcow";

/**
 * Admin deliverability stats fetch. Platform-area gated. Returns a discriminated
 * result so the UI can distinguish "not configured" from "unreachable" from live
 * data — it never throws out to the caller.
 */
export type MailStatsResult =
  | { state: "unconfigured" }
  | { state: "unreachable"; message: string }
  | { state: "ok"; stats: MailStats };

export async function refreshMailStats(): Promise<MailStatsResult> {
  await requireArea("platform");
  if (!mailcowConfigured()) return { state: "unconfigured" };
  try {
    const stats = await mcStats();
    return { state: "ok", stats };
  } catch (e) {
    return { state: "unreachable", message: e instanceof Error ? e.message : String(e) };
  }
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { StatCard, Badge } from "@/components/ui/primitives";
import { refreshMailStats, type MailStatsResult } from "@/lib/actions-mail-admin";

/**
 * Live deliverability panel. Seeded with a server-rendered result, then polls
 * refreshMailStats() every 30s. Degrades gracefully when Mailcow is
 * unconfigured or unreachable.
 */
export function MailAnalytics({ initial }: { initial: MailStatsResult }) {
  const [result, setResult] = useState<MailStatsResult>(initial);
  const [refreshing, setRefreshing] = useState(false);
  const [lastUpdated, setLastUpdated] = useState<number>(Date.now());

  const load = useCallback(async () => {
    setRefreshing(true);
    try {
      const next = await refreshMailStats();
      setResult(next);
      setLastUpdated(Date.now());
    } catch {
      // keep the previous result on a transient action failure
    } finally {
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    const t = setInterval(load, 30_000);
    return () => clearInterval(t);
  }, [load]);

  if (result.state === "unconfigured") {
    return (
      <Notice
        tone="amber"
        title="Mailcow not configured"
        body="Set MAILCOW_API_URL and MAILCOW_API_KEY for this app to enable mailbox provisioning and deliverability analytics."
      />
    );
  }

  if (result.state === "unreachable") {
    return (
      <div className="space-y-4">
        <div className="flex items-center justify-end">
          <RefreshButton onClick={load} refreshing={refreshing} />
        </div>
        <Notice
          tone="red"
          title="Mail server unreachable"
          body={`Could not reach the Mailcow API. ${result.message}`}
        />
      </div>
    );
  }

  const { stats } = result;
  const p = stats.postfix;
  const deliverySampled = p.sampled || 1;
  const deliveredPct = Math.round((p.sent / deliverySampled) * 100);
  const spamPct = stats.rspamd.sampled
    ? Math.round((stats.rspamd.spam / stats.rspamd.sampled) * 100)
    : 0;

  const rspamdActions = Object.entries(stats.rspamd.actions).sort((a, b) => b[1] - a[1]);

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="text-xs text-slate-500">
          Sampling the last {p.sampled} postfix events and {stats.rspamd.sampled} rspamd checks · updated{" "}
          {new Date(lastUpdated).toLocaleTimeString()}
        </p>
        <RefreshButton onClick={load} refreshing={refreshing} />
      </div>

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard label="Domains" value={String(stats.domains)} />
        <StatCard label="Mailboxes" value={String(stats.mailboxes)} />
        <StatCard label="Delivered" value={`${deliveredPct}%`} delta={`${p.sent} sent`} deltaGood />
        <StatCard
          label="Spam actions"
          value={`${spamPct}%`}
          delta={`${stats.rspamd.spam} flagged`}
          deltaGood={spamPct < 10}
        />
      </div>

      <div className="card">
        <h2 className="mb-4 font-semibold text-white">Postfix delivery (recent)</h2>
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          <Metric label="Sent" value={p.sent} tone="green" />
          <Metric label="Deferred" value={p.deferred} tone="amber" />
          <Metric label="Bounced" value={p.bounced} tone="red" />
          <Metric label="Rejected" value={p.rejected} tone="red" />
        </div>
        {p.other > 0 && (
          <p className="mt-3 text-xs text-slate-500">
            {p.other} other log line{p.other === 1 ? "" : "s"} not matching a delivery status.
          </p>
        )}
      </div>

      <div className="card">
        <h2 className="mb-4 font-semibold text-white">Rspamd actions (recent)</h2>
        {rspamdActions.length === 0 ? (
          <p className="text-sm text-slate-500">No rspamd history in the sampled window.</p>
        ) : (
          <div className="space-y-2">
            {rspamdActions.map(([action, count]) => {
              const pct = Math.round((count / (stats.rspamd.sampled || 1)) * 100);
              const bad = action === "reject" || action === "add header" || action === "rewrite subject";
              return (
                <div key={action} className="flex items-center gap-3">
                  <span className="w-36 shrink-0 text-sm capitalize text-slate-300">{action}</span>
                  <div className="h-2 flex-1 overflow-hidden rounded-full bg-white/[0.06]">
                    <div
                      className={`h-full rounded-full ${bad ? "bg-red-400" : "bg-emerald-400"}`}
                      style={{ width: `${pct}%` }}
                    />
                  </div>
                  <span className="w-16 shrink-0 text-right text-sm text-slate-400">
                    {count} ({pct}%)
                  </span>
                </div>
              );
            })}
          </div>
        )}
      </div>

      <div className="card border-amber-500/25 bg-amber-500/[0.05]">
        <div className="flex flex-wrap items-center gap-2">
          <h2 className="font-semibold text-white">DNS &amp; DMARC</h2>
          <Badge tone="amber">deliverability</Badge>
        </div>
        <p className="mt-2 text-sm text-slate-300">
          Strong deliverability needs correct DNS on every hosted domain: an MX record to the mail
          host, an SPF TXT record authorizing it, DKIM public keys published from Mailcow, and a
          DMARC policy (start at <span className="font-mono">p=none</span> for reporting, then tighten
          to <span className="font-mono">quarantine</span>/<span className="font-mono">reject</span>).
          A rising deferred/bounced or reject rate above usually points at a missing or misaligned
          SPF/DKIM/DMARC record rather than the mail server itself.
        </p>
      </div>
    </div>
  );
}

function RefreshButton({ onClick, refreshing }: { onClick: () => void; refreshing: boolean }) {
  return (
    <button className="btn-secondary py-1 text-xs" onClick={onClick} disabled={refreshing}>
      {refreshing ? "Refreshing…" : "Refresh"}
    </button>
  );
}

function Metric({
  label,
  value,
  tone,
}: {
  label: string;
  value: number;
  tone: "green" | "amber" | "red";
}) {
  const color =
    tone === "green" ? "text-emerald-400" : tone === "amber" ? "text-amber-400" : "text-red-400";
  return (
    <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-4">
      <p className="text-[13px] text-slate-400">{label}</p>
      <p className={`mt-1 text-2xl font-bold ${color}`}>{value}</p>
    </div>
  );
}

function Notice({
  tone,
  title,
  body,
}: {
  tone: "amber" | "red";
  title: string;
  body: string;
}) {
  const cls =
    tone === "amber"
      ? "border-amber-500/30 bg-amber-500/[0.06]"
      : "border-red-500/30 bg-red-500/[0.06]";
  return (
    <div className={`card ${cls}`}>
      <div className="flex flex-wrap items-center gap-2">
        <h2 className="font-semibold text-white">{title}</h2>
        <Badge tone={tone}>{tone === "amber" ? "action needed" : "error"}</Badge>
      </div>
      <p className="mt-2 text-sm text-slate-300">{body}</p>
    </div>
  );
}

import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge } from "@/components/ui/primitives";
import { MailAnalytics } from "@/components/admin/MailAnalytics";
import { refreshMailStats } from "@/lib/actions-mail-admin";

export const dynamic = "force-dynamic";

export default async function AdminMailPage() {
  await requireArea("platform");

  // Server-render an initial snapshot; the client component then polls.
  const initial = await refreshMailStats();

  const tone =
    initial.state === "ok" ? "green" : initial.state === "unconfigured" ? "amber" : "red";
  const label =
    initial.state === "ok"
      ? "connected"
      : initial.state === "unconfigured"
        ? "not configured"
        : "unreachable";

  return (
    <div>
      <PageHeader
        title="Mail deliverability"
        sub="Live Mailcow delivery + spam analytics for hosted business-email domains."
      >
        <Badge tone={tone}>{label}</Badge>
      </PageHeader>

      <MailAnalytics initial={initial} />
    </div>
  );
}

